// raw/*.png (generated by generate.mjs) → the files the web home draws:
//   world-education / world-games → apps/client/public/home/world-*.webp (the mode choice's halves)
//   mascot                        → apps/client/public/home/mascot.webp  (trimmed, on the way-in card)
//   hero-village                  → apps/client/public/backgrounds/craftyap-village-open-{desktop,mobile}.webp
//                                   (the still under the menu video: its 16:9 middle, as the video's first frame)
// Encoded in headless Edge (no native image library in this repo).
//
//   node assets/web-home/build.mjs
import { createRequire } from "node:module";
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = join(HERE, "../..");
const PUBLIC = join(ROOT, "apps/client/public");
const puppeteer = createRequire(join(ROOT, "package.json"))("puppeteer-core");
const EDGE = "C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe";

// [raw name, output (under public/), width, height, quality, crop: [x, y, w, h] of the raw | "trim"]
const JOBS = [
  ["world-education", "home/world-education.webp", 1536, 1024, 0.8],
  ["world-games", "home/world-games.webp", 1536, 1024, 0.8],
  ["mascot", "home/mascot.webp", 360, 360, 0.9, "trim"],
  // the three previews: the middle band of each (the scenes are painted there)
  ["preview-build", "home/preview-build.webp", 600, 273, 0.76, [0, 162, 1536, 700]],
  ["preview-machine", "home/preview-machine.webp", 600, 273, 0.76, [0, 162, 1536, 700]],
  ["preview-class", "home/preview-class.webp", 600, 273, 0.76, [0, 162, 1536, 700]],
  // the guide's classroom picture: the same class, larger
  ["preview-class", "home/class-together.webp", 1152, 648, 0.84, [0, 120, 1536, 864]],
  // the lesson select's big pictures (one per lesson)
  ["lesson-fire", "home/lesson-fire.webp", 1152, 513, 0.84, [0, 170, 1536, 684]],
  ["hero-village", "backgrounds/craftyap-village-open-desktop.webp", 1280, 720, 0.72, [0, 80, 1536, 864]],
  ["hero-village", "backgrounds/craftyap-village-open-mobile.webp", 854, 480, 0.72, [0, 80, 1536, 864]],
];

const browser = await puppeteer.launch({ executablePath: EDGE, headless: "new", args: ["--no-sandbox"] });
const page = await browser.newPage();
for (const [name, out, w, h, q, crop] of JOBS) {
  const raw = join(HERE, "raw", `${name}.png`);
  if (!existsSync(raw)) { console.log(`MISS ${name} (run generate.mjs)`); continue; }
  const [data, ow, oh] = await page.evaluate(async (b64, w, h, q, crop) => {
    const img = new Image(); img.src = `data:image/png;base64,${b64}`; await img.decode();
    let [sx, sy, sw, sh] = Array.isArray(crop) ? crop : [0, 0, img.naturalWidth, img.naturalHeight];
    if (crop === "trim") { // the box of what is not transparent
      const t = document.createElement("canvas"); t.width = sw; t.height = sh;
      const tc = t.getContext("2d"); tc.drawImage(img, 0, 0);
      const px = tc.getImageData(0, 0, sw, sh).data;
      let x0 = sw, y0 = sh, x1 = 0, y1 = 0;
      for (let y = 0; y < sh; y++) for (let x = 0; x < sw; x++) if (px[(y * sw + x) * 4 + 3] > 8) { if (x < x0) x0 = x; if (x > x1) x1 = x; if (y < y0) y0 = y; if (y > y1) y1 = y; }
      [sx, sy, sw, sh] = [x0, y0, x1 - x0 + 1, y1 - y0 + 1];
      const scale = Math.min(w / sw, h / sh); w = Math.round(sw * scale); h = Math.round(sh * scale);
    }
    const c = document.createElement("canvas"); c.width = w; c.height = h;
    const ctx = c.getContext("2d"); ctx.imageSmoothingQuality = "high";
    ctx.drawImage(img, sx, sy, sw, sh, 0, 0, w, h);
    return [c.toDataURL("image/webp", q).split(",")[1], w, h];
  }, readFileSync(raw).toString("base64"), w, h, q, crop ?? null);
  writeFileSync(join(PUBLIC, out), Buffer.from(data, "base64"));
  console.log(`${out}  ${ow}x${oh}  ${Math.round(Buffer.from(data, "base64").length / 1024)} KB`);
}
await browser.close();
